<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($title??'POS System') ?></title><style>body{font-family:Arial;margin:0;background:#f4f6f8;color:#17202a}.nav{background:#17202a;padding:15px}.nav a{color:white;margin-right:18px;text-decoration:none}.wrap{max-width:1100px;margin:25px auto;background:white;padding:25px;border-radius:8px}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}.btn{display:inline-block;padding:8px 12px;background:#2563eb;color:white;text-decoration:none;border:0;border-radius:4px;cursor:pointer}.danger{background:#dc2626}.card{display:inline-block;background:#eef2ff;padding:20px;margin:8px;border-radius:8px;min-width:160px}.alert{padding:10px;margin:10px 0;background:#fee2e2}.ok{background:#dcfce7}input,select{padding:9px;width:100%;box-sizing:border-box;margin:5px 0 15px}label{font-weight:bold}.thumb{width:50px;height:50px;object-fit:cover}</style></head><body><div class="nav"><a href="/dashboard">Dashboard</a><a href="/products">Products</a><a href="/customers">Customers</a><a href="/staff">Staff</a><a href="/sales/new">Record Sale</a><a href="/sales">Sales History</a><a href="/logout">Logout</a></div><main class="wrap"><h1><?= esc($title??'POS System') ?></h1><?php if(session('error')): ?><div class="alert"><?= esc(session('error')) ?></div><?php endif ?><?php if(session('success')): ?><div class="alert ok"><?= esc(session('success')) ?></div><?php endif ?><?php if(session('errors')): ?><div class="alert"><?= implode('<br>',array_map('esc',session('errors'))) ?></div><?php endif ?>
